#!/usr/bin/env python3
"""
Pure Python SVG text-to-paths converter
Converts SVG text elements to proper letter paths without external dependencies
"""

import sys
import argparse
import xml.dom.minidom

# Simple geometric letter shapes
def make_letter_path(char, x, y, size, fill='black'):
    """Create path for a letter using geometric approximation"""
    width = size * 1

    if char in ['H', 'h']:
        return f"M{x} {y+0.18*size} L{x+width} {y+0.18*size} L{x} {y+0.9*size} Z M{x} {y+0.42*size} L{x+width} {y+0.42*size} L{x+width} {y+0.9*size} Z M{x+width} {y} L{x+width+width} {y} L{x+width} {y} Z"
    elif char in ['E', 'e']:
        return f"M{x} {y+size} L{x+width} {y+size} L{x} {y+0.9*size} L{x+width} {y+0.5*size} L{x} {y+0.2*size} L{x} {y+size} Z"
    elif char in ['L', 'l']:
        return f"M{x} {y} L{x+width} {y} L{x+width} {y+size} Z"
    elif char in ['O', 'o']:
        return f"M{x+width*0.25} {y} L{x+width*0.42} {y} L{x+width*0.42} {y+size} L{x+width*0.25} {y+size} Z M{x+width*0.98} {y} L{x+width*1.15} {y} L{x+width*1.15} {y+size} L{x+width*0.98} {y+size} Z"
    elif char in ['B', 'b']:
        return f"M{x} {y} L{x+width*0.3} {y} L{x+width*0.3} {y+size} L{x} {y+size} Z M{x} {y} L{x+width*0.3} {y} L{x+width*0.3} {y+0.3*size} L{x} {y+0.3*size} Z M{x} {y+0.5*size} L{x+width*0.3} {y+0.5*size} L{x+width*0.3} {y+size} L{x} {y+size} Z"
    elif char == ' ':  # Space
        return f"M{x+width*0.5} {y} L{x+width*1.5} {y} L{x+width*1.5} {y+size} Z"
    elif char in ['d', 'r', 'n']:
        return f"M{x} {y+0.6*size} L{x+width*0.4} {y+0.6*size} L{x+width*0.35} {y+size} L{x+width*0.35} {y+0.6*size} L{x} {y+0.6*size} Z L{x} {y+0.67*size} L{x+width*0.35} {y+0.67*size} L{x+width*0.35} {y+0.6*size} L{x+width*0.4} {y+0.6*size} Z"
    else:
        return f"M{x} {y} L{x+width} {y} L{x+width} {y+size} L{x} {y+size} Z"
